"""Pydantic schemas for Adaptive Engine recommendations, diagnostics, and mastery reports."""

from typing import List, Optional
from pydantic import BaseModel, ConfigDict


class WeakConceptItem(BaseModel):
    """Concept diagnosed as needing reinforcement."""
    skill_id: int
    skill_slug: str
    skill_title: str
    category: str
    mastery_score: float
    status: str
    error_rate: float
    recommended_action: str
    reason: str


class AdaptiveRecommendationResponse(BaseModel):
    """Next optimal learning activity generated by the Adaptive Engine with explainability."""
    recommendation_type: str  # 'revision', 'practice', 'advance_skill', 'project'
    activity_type: str  # 'assessment', 'practice', 'project', 'review'
    target_skill_id: Optional[int] = None
    target_skill_slug: Optional[str] = None
    target_skill_title: Optional[str] = None
    category: Optional[str] = None
    difficulty: str = "beginner"
    reason: str
    prerequisites_satisfied: bool = True
    missing_prerequisites: List[str] = []
    related_project_id: Optional[int] = None
    confidence_score: float = 0.5


class LearnerMasteryOverview(BaseModel):
    """Holistic summary of a learner's knowledge profile across domains."""
    total_skills: int
    mastered_count: int
    in_progress_count: int
    locked_count: int
    average_mastery: float
    weak_concepts: List[WeakConceptItem]
